import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天泽履","description":"周易折中 - 天泽履","frontmatter":{"title":"天泽履","description":"周易折中 - 天泽履"},"headers":[],"relativePath":"zh/classics/zhezhong/016.md","filePath":"zh/classics/zhezhong/016.md"}'),h={name:"zh/classics/zhezhong/016.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="天泽履" tabindex="-1">天泽履 <a class="header-anchor" href="#天泽履" aria-label="Permalink to “天泽履”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>履序卦，物畜然后有礼，故受之以履。夫物之聚，则有大小之别，高下之等，美恶之分，是物畜然后有礼。履所以继畜也。履，礼也，礼人之所履也。为卦天上泽下，天而在上，泽而处下，上下之分，尊卑之义，理之当也。礼之本也，常履之道也，故为履。履，践也，藉也。履物为践，履于物为藉。以柔藉刚，故为履也。不曰刚履柔，而曰柔履刚者，刚乘柔常理不足道，故《易》中惟言柔乘刚，不言刚乘柔也。言履藉于刚，乃见卑顺说应之义。</p><p>履：履虎尾，不咥人，亨</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>兑亦三画卦之名，一阴见于二阳之上，故其徳为说，其象为泽。履，有所蹑而进之义也。以兑遇乾，和说以蹑刚强之后，有履虎尾而不见伤之象，故其卦为履，而占如是也。人能如是，则处危而不伤矣。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>履，人所履之道也。天在上而泽处下，以柔履藉于刚，上下各得其义，事之至顺，理之至当也。人之履行如此，虽履至危之地，亦无所害，故履虎尾而不见其咥啮，所以能亨也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云：履上乾下兑，以阴蹑阳，是随后蹑他，如踏他脚迹相似，所以云“履虎尾”。卦之三四爻发“虎尾”义，便是阴去蹑他阳后处。</li></ul><p>朱子语类云：履上乾下兑，以阴蹑阳，是随后蹑他，如踏他脚迹相似，所以云“履虎尾”。卦之三四爻发“虎尾”义，便是阴去蹑他阳后处。</p><ul><li>李氏简曰：履，礼也，行之以和，故能进退履众刚而不见伤。礼之用和为贵，其是之谓乎？</li></ul><p>李氏简曰：履，礼也，行之以和，故能进退履众刚而不见伤。礼之用和为贵，其是之谓乎？</p><ul><li>胡氏炳文曰：程传训履为践、为藉，以上下论也。本义云有所蹑而进，以前后论也。于“尾”字为切。诸家多以兑为虎，本义从程传以乾为虎，本夫子彖传意也。“不咥人亨”，大抵人之涉世多是危机，不为所伤，乃见所履。大传曰：“《易》之兴也，其当文王与纣之事邪？是故其辞危。”危莫危于履虎尾之辞矣，故九卦处忧患以履为首。</li></ul><p>胡氏炳文曰：程传训履为践、为藉，以上下论也。本义云有所蹑而进，以前后论也。于“尾”字为切。诸家多以兑为虎，本义从程传以乾为虎，本夫子彖传意也。“不咥人亨”，大抵人之涉世多是危机，不为所伤，乃见所履。大传曰：“《易》之兴也，其当文王与纣之事邪？是故其辞危。”危莫危于履虎尾之辞矣，故九卦处忧患以履为首。</p><ul><li>梁氏寅曰：履者，践履也。人之于礼，亦践行其天理者，故履为礼也。夫虎，刚猛之兽，乾三阳虎之象也。上为虎之首，则四为虎之尾。兑履乾之后，履虎尾之象也。虎咥人者也，然以和说履之，则不见咥而反致亨。以是观之，人之践履卑逊，何往而不亨乎？然和非阿容也，说非佞媚也，亦恭顺而不失其正耳。兑之传曰：“刚中而柔外”，此其道也。</li></ul><p>梁氏寅曰：履者，践履也。人之于礼，亦践行其天理者，故履为礼也。夫虎，刚猛之兽，乾三阳虎之象也。上为虎之首，则四为虎之尾。兑履乾之后，履虎尾之象也。虎咥人者也，然以和说履之，则不见咥而反致亨。以是观之，人之践履卑逊，何往而不亨乎？然和非阿容也，说非佞媚也，亦恭顺而不失其正耳。兑之传曰：“刚中而柔外”，此其道也。</p><ul><li>蔡氏清曰：八卦惟兑为至弱，惟乾为至健。今以至弱者而蹑于至健者之后，自是危机，故独以履名卦。而彖传复取其德，而谓之“履虎尾，不咥人亨”也。</li></ul><p>蔡氏清曰：八卦惟兑为至弱，惟乾为至健。今以至弱者而蹑于至健者之后，自是危机，故独以履名卦。而彖传复取其德，而谓之“履虎尾，不咥人亨”也。</p><p>象曰：上天下泽，履。君子以辨上下，定民志</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>程传备矣。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>天在上，泽居下，上下之正理也。人之所履当如是，故取其象而为履。君子观履之象，以辨别上下之分，以定其民志。夫上下之分明，然后民志有定；民志定，然后可以言治。民志不定，天下不可得而治也。古之时，公卿大夫而下，位各称其德，终身居之，得其分也。位未称德，则君举而进之；士修其学，学至而君求之，皆非有预于己也。农工商贾勤其事，而所享有限，故皆有定志，而天下之心可一。后世自庶士至于公卿，日志于尊荣；农工商贾，日志于富侈。亿兆之心交骛于利，天下纷然，如之何其可一也？欲其不乱，难矣！此由上下无定志也。君子观履之象，而分辨上下，使各当其分，以定民之心志也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问履如何都作礼字说，曰：“礼主卑下，履也是那践履处，所行若不由礼，自是乖戾，所以曰‘履以和行’。”</p></li><li><p>王氏应麟曰 ：“上天下泽，履，此易之言礼；雷出地奋，豫，此易之言乐。”吕成公之说本于《汉书》，“上天下泽，春雷奋作，先王观象爰制礼乐。”</p></li><li><p>何氏楷曰 ：“天高地下，天尊地卑，泽又下之下，卑之卑者。”</p></li></ul><p>彖曰：履柔履刚也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以二体释卦名义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰 ：履以六三成卦，三之象下迫于二阳之进，上蹑乎三阳之刚。</p></li><li><p>胡氏炳文曰 ：本义谓二体见得，是以兑体之柔履乾体之刚，非指六三以柔而履刚也。案王氏、胡氏二说不同，然当兼用其义乃备。</p></li></ul><p>说而应乎乾，是以履虎尾不咥人，亨</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦德释彖辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>兑以阴柔履藉乾之阳刚，柔履刚也。兑以说顺应乎乾刚而履藉之下，顺乎上，阴承乎阳，天下之正理也。所履如此，至顺至当，虽履虎尾亦不见伤害，以此履行其亨可知。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>游氏酢曰 ：卦以一柔进退履众刚，故有履虎尾之象。然而不咥人亨者，说而应乎乾故也。夫敬以和，何事不行？君子之所履，苟在于是，则虽暴人之前无虞矣。</p></li><li><p>项氏安世曰 ：以兑说而应乎乾，则所行无忤，履虽危而不伤。庄周曰：“虎媚养己者，顺也。”惟柔顺而说，则履虎尾而不咥人，且有能亨之理。</p></li><li><p>胡氏炳文曰 ：说而应乎乾，亦是以下体之兑应上体之乾。若蒙曰“志应”，师曰“刚中而应”，是刚柔两爻自相应；比、小畜上下应，是一爻为主而众爻应之。</p></li></ul><p>刚中正，履帝位而不疚，光明也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>又以卦体明之，指九五也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>九五以阳刚中正尊履帝位，苟无疚病，得履道之至善，光明者也。疚谓疵病，夬履是也。光明德盛而辉光也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏浚曰 ：九五履乾正位，曰刚中正，刚健不息，体大中至正之道，以君临天下，履帝位而不疚也。君临天下者，其可危为大。盖人君以一身抚驭海内，使所履一不正而蹈于非礼，则政令纪纲弛于上，谗贼寇攘起于下。穆王命君牙曰：“心之忧危，若蹈虎尾，涉于春冰”是也。</li></ul><p>初九：素履往，无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>以阳在下，居履之初，未为物迁，率其素履者也。占者如是，则往而无咎也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>履，不处者行之义。初处至下，素在下者也。而阳刚之才，可以上进，若安其卑下之素而往，则无咎矣。夫人不能自安于贫贱之素，则其进也，乃贪躁而动，求去乎贫贱耳，非欲有为也。既得其进，骄溢必矣。故往则有咎。贤者则安履其素，其处也乐，其进也将有为也。故得其进，则有为而无不善，乃守其素履者也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：初未交于物，有素象。案《本义》与蔡氏皆曰：“居履之初，不为物迁。”蔡氏则曰：“素者，无文之谓。”盖履礼也，履初言素，礼以质为本也。贲，文也，贲上言白，文之极反而质也。白贲无咎，其即素履往无咎与？</li></ul><p>象曰：素履之往，独行愿也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>安履其素而往者，非苟利也，独行其志愿耳。独，专也。若欲贵之心与行道之心交战于中，岂能安履其素也？</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏心传曰 ：素履往，即中庸所谓“素位而行”者也；独行愿，即中庸所谓“不愿乎其外”者也。</li></ul><p>九二：履道坦坦，幽人贞吉</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>刚中在下，无应于上，故为履道平坦，幽独守贞之象。幽人履道而遇其占，则贞而吉矣。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>九二居柔寛裕，得中，其所履坦坦然平易之道也。虽所履得坦易之道，亦必幽静安恬之人处之，则能贞固而吉也。九二阳志上进，故有幽人之戒。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰：行于道路者，由中则平坦，从旁则崎险。九二以刚居中，是履道而得其平坦者也。持身如是，不轻自售，故为“幽人贞吉”。</li></ul><p>象曰：幽人贞吉，中不自乱也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>履道在于安静，其中恬正则所履安裕。中若躁动，岂能安其所履？故必幽人则能坚固而吉。盖其中心安静，不以利欲自乱也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>谷氏家杰曰 ：初之素而曰行愿，二之坦而曰不乱，可见其身之履皆由于志之定也。</li></ul><p>六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六三不中不正，柔而志刚，以此履干，必见伤害，故其象如此。而占者凶，又为刚武之人得志而肆暴之象，如秦政、项籍，岂能久也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三以阴居阳，志欲刚而体本阴柔，安能坚其所履，故如盲眇之视，其见不明；跛躄之履，其行不远。才既不足，而又处不得中，履非其正。以柔而务刚，其履如此，是履于危地，故曰“履虎尾”。以不善履，履危地必及祸患，故曰“咥人凶”。武人为于大君，如武暴之人而居人上，肆其躁率而已，非能顺履而远到也。不中正而志刚，乃为群阳所与，是以刚躁蹈危而得凶也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>耿氏南仲曰：视欲正视而不正则眇者，行欲中行而不中则跛者也。故归妹初九不中则为跛，九二不正则为眇。履六三不中又不正，故跛眇兼焉。归妹、履皆兑下也。</li></ul><p>耿氏南仲曰：视欲正视而不正则眇者，行欲中行而不中则跛者也。故归妹初九不中则为跛，九二不正则为眇。履六三不中又不正，故跛眇兼焉。归妹、履皆兑下也。</p><ul><li>王氏申子曰：三以阴居阳，以柔履刚，谓其明耶，则众阳而独阴；谓其不明耶，则又居于阳，眇能视之象也。谓其能行耶，则众刚而独柔；谓其不能行耶，则又履乎刚，跛能履之象也。是体暗而用明，才弱而志刚者也。而又不中不正，故不自度量而一于进，敢于蹈危而取祸，如履虎尾而受咥人之凶也。若不顾强弱，勇猛直前，惟武人用之以有为于大君之事则可。然彖亦主三而言曰“不咥人亨”，此曰“咥人凶”，何也？盖彖总言一卦之体，爻则据其时与位而言，所以不同。</li></ul><p>王氏申子曰：三以阴居阳，以柔履刚，谓其明耶，则众阳而独阴；谓其不明耶，则又居于阳，眇能视之象也。谓其能行耶，则众刚而独柔；谓其不能行耶，则又履乎刚，跛能履之象也。是体暗而用明，才弱而志刚者也。而又不中不正，故不自度量而一于进，敢于蹈危而取祸，如履虎尾而受咥人之凶也。若不顾强弱，勇猛直前，惟武人用之以有为于大君之事则可。然彖亦主三而言曰“不咥人亨”，此曰“咥人凶”，何也？盖彖总言一卦之体，爻则据其时与位而言，所以不同。</p><ul><li>吴氐澄曰：彖通指一卦而言，则上九为虎之首，虎口实而合，有不咥之象。此专据一爻而言，则三为兑之上画，兑口虚而开，故有咥人之象。</li></ul><p>吴氐澄曰：彖通指一卦而言，则上九为虎之首，虎口实而合，有不咥之象。此专据一爻而言，则三为兑之上画，兑口虚而开，故有咥人之象。</p><ul><li>胡氏炳文曰：凡卦辞以爻为主，则爻辞与卦同，如屯卦“利建侯”，而初爻亦“利建侯”。以卦上下体论，则爻辞与卦不同，如此卦云“履虎尾不咥人”，而六三则曰“咥人”是也。卦书“不咥人”，兑三爻说体自与干三爻健体相应也。爻书“咥人”，六三一爻与上九一爻独相应，履虎尾而首应也。</li></ul><p>胡氏炳文曰：凡卦辞以爻为主，则爻辞与卦同，如屯卦“利建侯”，而初爻亦“利建侯”。以卦上下体论，则爻辞与卦不同，如此卦云“履虎尾不咥人”，而六三则曰“咥人”是也。卦书“不咥人”，兑三爻说体自与干三爻健体相应也。爻书“咥人”，六三一爻与上九一爻独相应，履虎尾而首应也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>武人为于大君，王氏之说得之。盖三非大君之位，且“为于”两字语气亦不顺也。子曰：“暴虎冯河，死而无悔者，吾不与也。”即此句之意。</p><p>象曰：眇能视，不足以有明也；跛能履，不足以与行也；咥人之凶，位不当也；武人为于大君，志刚也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>阴柔之人，其才不足。视不能明，行不能远，而乃务刚，所履如此，其能免于害乎？以柔居三，履非其正，所以致祸害，被咥而凶也。以武人为喻者，以其处阳才弱而志刚也。志刚则妄动，所履不由其道，如武人而为大君也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：三质暗才弱，本不足以有为。以当履之时，一阴为主，适与时遇，是以不顾其位不当，勇于行而履危蹈祸。斯道也，唯武人用之以为王事，一于进以行其志之刚则可。故爻辞于“咥人凶”后言之，用各有当也。</li></ul><p>九四：履虎尾，诉诉，终吉</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>九四亦以不中不正履九五之刚，然以刚居柔，故能戒惧而得终吉。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四阳刚而干体，虽居四刚胜之地，在近君多惧之地，无相得之义。五复刚决之过，故为履虎尾，诉诉畏惧之貌。若能畏惧，则当终吉。盖九虽刚而志柔，四虽近而不处，故能兢愼畏惧，则终免于危而获吉也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：逼近至尊，以阳承阳，处多惧之地，故曰“履虎尾，诉诉”也。然以阳居阴，以谦为本，虽处危惧，终获其志，故终吉也。</li></ul><p>王氏弼曰：逼近至尊，以阳承阳，处多惧之地，故曰“履虎尾，诉诉”也。然以阳居阴，以谦为本，虽处危惧，终获其志，故终吉也。</p><ul><li>王氏宗传曰：经曰：“四多惧。”处多惧之地，而复以恐惧自处，所谓“诉诉”也。四处三阳之后，故亦曰“履虎尾”。无忘其“诉诉”之戒，故曰“终吉”。在卦德曰“履虎尾，不咥人亨”，其九四之谓乎？</li></ul><p>王氏宗传曰：经曰：“四多惧。”处多惧之地，而复以恐惧自处，所谓“诉诉”也。四处三阳之后，故亦曰“履虎尾”。无忘其“诉诉”之戒，故曰“终吉”。在卦德曰“履虎尾，不咥人亨”，其九四之谓乎？</p><ul><li>朱子语类云：履三爻正是蹑他虎尾处，四上蹑五，亦为虎尾之象。</li></ul><p>朱子语类云：履三爻正是蹑他虎尾处，四上蹑五，亦为虎尾之象。</p><ul><li>胡氏炳文曰：《本义》于三之“履虎尾”曰“不中不正以履干”，是以干为虎，而三在其后也。于四之“履虎尾”则曰“亦以不中不正履九五之刚”，是以九五为虎，而四在其后也。三四皆不中正，而占有不同者，三多凶，以柔居刚，其凶也宜；四多惧，以刚居柔，所以终吉。</li></ul><p>胡氏炳文曰：《本义》于三之“履虎尾”曰“不中不正以履干”，是以干为虎，而三在其后也。于四之“履虎尾”则曰“亦以不中不正履九五之刚”，是以九五为虎，而四在其后也。三四皆不中正，而占有不同者，三多凶，以柔居刚，其凶也宜；四多惧，以刚居柔，所以终吉。</p><p>象曰：诉诉终吉，志行也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>能诉诉畏惧，则终得其吉者，志在于行而不处也。去危则获吉矣。阳刚能行者，居柔以顺自处者也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏过曰 ：畏惧所以行其志也。</p></li><li><p>王氏申子曰 ：三与四皆履虎尾者，三凶而四吉何也？三柔而志刚，勇于行而不知惧；四刚而志柔，谨于行而知所惧。惧则能防，是以终吉。其吉者，上进之志行也。</p></li><li><p>沈氏一贯曰 ：合而言之，则干为虎；离而言之，惟五为虎。故九四亦有履虎尾之象。以九居四，正与六三相反，故其志行。</p></li></ul><p>九五：夬履，贞厉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九五以刚中正履帝位，而下以兑说应之，凡事必行，无所疑碍，故其象为夬决。其履虽使得正，亦危道也，故其占为虽正而危，为戒深矣。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>夬，刚决也。五以阳刚干体居至尊之位，任其刚决而行者也。如此则虽得正，犹危厉也。古之圣人居天下之尊，明足以照，刚足以决，势足以专，然而未尝不尽天下之议，虽刍荛之微必取，乃其所以为圣也。履帝位而光明者也，若自任刚明决行不顾，虽使得正，亦危道也。可固守乎？有刚明之才，苟专自任，犹为危道，况刚眀不足者乎？《易》中云“贞厉”，义各不同，随卦可见。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰：六三于彖辞为亨者，以下卦言之，有和说之徳也；于本爻为凶者，资本阴柔履位不正，宜其凶也。九五于彖辞为不疚者，以上卦言之，有刚健中正之德也；于本爻为厉者，以刚行刚，志在夬决，其理虽正，其事则危也。凡彖多言卦德，凡爻多论爻位。</li></ul><p>项氏安世曰：六三于彖辞为亨者，以下卦言之，有和说之徳也；于本爻为凶者，资本阴柔履位不正，宜其凶也。九五于彖辞为不疚者，以上卦言之，有刚健中正之德也；于本爻为厉者，以刚行刚，志在夬决，其理虽正，其事则危也。凡彖多言卦德，凡爻多论爻位。</p><ul><li>王氏申子曰：履之卦义履刚也，履刚之道尚柔不尚刚也。五虽中正，以履帝位，然以刚居刚，是一于尚刚者也。“夬履”谓决于行也，一于任刚决行而不顾，则于中正之道岂能无咎乎？若贞固守此危道也，故曰“贞厉”。</li></ul><p>王氏申子曰：履之卦义履刚也，履刚之道尚柔不尚刚也。五虽中正，以履帝位，然以刚居刚，是一于尚刚者也。“夬履”谓决于行也，一于任刚决行而不顾，则于中正之道岂能无咎乎？若贞固守此危道也，故曰“贞厉”。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>凡彖传中所赞美，则其爻辞无凶厉者，何独此爻不然？盖履道贵柔，九五以刚居刚，是决于履也。然以其有中正之德，故能常存危厉之心，则虽决于履，而动可无过举矣。《书》云：“心之忧危，若蹈虎尾。”此其所以履帝位而不疚也。与凡《易》中“贞厉”，有厉有以常存危惧之心为义者，如噬嗑之“贞厉无咎”，夬之“其危乃光”是也。然则此之“贞厉”，兑五之有厉，当从此例也。</p><p>象曰：夬履贞厉，位正当也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>伤于所恃。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>戒夬履者，以其正当尊位也。居至尊之位，据能专之势，而自任刚决，不复畏惧，虽使得正，亦危道也。</p><p>上九：视履考祥，其旋元吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>视履之终，以考其祥。周旋无亏，则得元吉。占者祸福视其所履而未定也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>一处履之终，于其终视其所履行，以考其善恶祸福。若其旋，则善且吉也。旋谓周旋完备，无不至也。人之所履，考视其终，若终始周完无疚，善之至也，是以元吉。人之吉凶，系其所履善恶之多寡，吉凶之小大也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：祸福之祥，生乎所履。处履之极，履道成矣，故可视履而考祥也。居极应说，高而不危，是其旋也。履道大成，故元吉。</li></ul><p>王氏弼曰：祸福之祥，生乎所履。处履之极，履道成矣，故可视履而考祥也。居极应说，高而不危，是其旋也。履道大成，故元吉。</p><ul><li>梁氏寅曰：上履之终也。人之所履，观之于始，则诚伪未可见，惟观之于终，然后见也。故视其所履，以考其善。若周旋无亏，则其吉大矣。是爻也，岂非动容周旋中礼，而为盛德之至与？</li></ul><p>梁氏寅曰：上履之终也。人之所履，观之于始，则诚伪未可见，惟观之于终，然后见也。故视其所履，以考其善。若周旋无亏，则其吉大矣。是爻也，岂非动容周旋中礼，而为盛德之至与？</p><p>总论</p><ul><li><p>项氏安世曰：一阴一阳之卦，在下者为复、姤，在上者为夬、剥。其义主于消长也。在二五者，阳在二为师之将，在五为比之主；阴在二为同人之君子，在五为大有之君子。其义主于得位也。在三四者，阳在三则以刚行柔为劳谦，在四则以刚制柔为由豫；阴在三则以柔行刚为履，在四则以柔制刚为小畜。其义主于用事也。大抵用事之爻，在下者为行己之事，在上者为制人之事。 又曰：履之六爻皆以履柔为吉，故九二为坦坦，九四为诉诉终吉，上九为其旋元吉，皆履柔也。六三卦辞本善，终以履刚为凶。初九、九五所履皆正，然初仅能无咎，五不免于厉，皆履刚也。是故初则惧其失初心之正，而教之以保其素；五则惧其恃势位之正，而教之以谨其决。盖刚者喜动而好决，任刚而行者，后多可悔之事也。</p></li><li><p>又曰：履之六爻皆以履柔为吉，故九二为坦坦，九四为诉诉终吉，上九为其旋元吉，皆履柔也。六三卦辞本善，终以履刚为凶。初九、九五所履皆正，然初仅能无咎，五不免于厉，皆履刚也。是故初则惧其失初心之正，而教之以保其素；五则惧其恃势位之正，而教之以谨其决。盖刚者喜动而好决，任刚而行者，后多可悔之事也。</p></li></ul><p>象曰：元吉在上，大有庆也</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>若得元吉，则大有福庆也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>上履之终也。人之所履，善而吉至其终，周旋无亏，乃大有福庆之人也。人之行，贵乎有终。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>林氏希元曰 ：在上，履之终也。言于履之终而得元吉，则大有福庆也。“在上”是解所以元吉，“大有庆”是正解元吉。</li></ul>',145)])])}const u=l(h,[["render",p]]);export{b as __pageData,u as default};
